<?php
declare(strict_types=1);
$themeRoot=dirname(__DIR__,3); $wpRoot='/opt/wp-testbed';
$failures=[];$assert=static function(bool $c,string $l)use(&$failures):void{echo $c?"  [PASS] $l\n":"  [FAIL] $l\n"; if(!$c)$failures[]=$l;};
echo "=== [TEST] Task 2.8 Media & Repeater Fields ===\n";
require_once $wpRoot.'/wp-load.php';
use ErfanSanat\Theme\Admin\Fields\{MediaField,RepeaterField};
$h=MediaField::render('favicon_id','فاوآیکون',0); $assert(str_contains($h,'data-es-media-select="favicon_id"'),'media select button'); $assert(str_contains($h,'data-es-media-remove'),'media remove button');
$assert(str_contains($h,'data-es-media-preview-slot'),'empty media field has a stable preview mount');
$adminJs=(string)file_get_contents("$themeRoot/assets/admin/js/admin-dashboard.js");
foreach(['wp.media','data-es-media-select','data-es-media-remove','data-es-save-options','data-es-export-options','data-es-import-options','data-es-reset-options'] as $hook) $assert(str_contains($adminJs,$hook),"Admin JS handles $hook");
$h=RepeaterField::render('links','لینک‌ها',[['key'=>'text','label'=>'عنوان'],['key'=>'url','label'=>'آدرس']],[['text'=>'الف','url'=>'https://a.test'],['text'=>'ب','url'=>'']]);
$assert(substr_count($h,'data-es-repeater-index="0"')===1&&substr_count($h,'data-es-repeater-index="1"')===1,'repeater renders 2 live items and a separate template'); $assert(str_contains($h,'options[links][1][url]'),'repeater indexed input names'); $assert(str_contains($h,'data-es-repeater-add'),'repeater add button');
$assert(str_contains($h,'data-es-repeater-template') && str_contains($h,'__INDEX__'),'repeater includes an empty-state-safe item template');
$assert(str_contains($h,'data-es-repeater-move-up') && str_contains($h,'data-es-repeater-move-down'),'repeater offers accessible move controls');
$assert(str_contains($adminJs,'data-es-repeater-add') && str_contains($adminJs,'data-es-repeater-remove'),'Admin JS handles repeater add/remove');
$assert(str_contains($adminJs,'data-es-repeater-move-up') && str_contains($adminJs,'updateRepeaterCount'),'Admin JS reorders items and reindexes input names');
$emptyRepeater=RepeaterField::render('empty_links','لینک‌ها',[['key'=>'text','label'=>'عنوان']],[]);
$assert(str_contains($emptyRepeater,'data-es-repeater-template')&&substr_count($emptyRepeater,'data-es-repeater-item')===1,'Empty repeater remains addable through its template');
if($failures){fwrite(STDERR,"[FAILED]\n");exit(1);} echo "\n[PASSED] Task 2.8\n";
